CREATE TABLE ezsearch_object_word_link (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, contentclass_attribute_id INTEGER DEFAULT 0 NOT NULL, contentclass_id INTEGER DEFAULT 0 NOT NULL, contentobject_id INTEGER DEFAULT 0 NOT NULL, frequency DOUBLE PRECISION DEFAULT '0' NOT NULL, identifier VARCHAR(255) DEFAULT '' NOT NULL, integer_value INTEGER DEFAULT 0 NOT NULL, next_word_id INTEGER DEFAULT 0 NOT NULL, placement INTEGER DEFAULT 0 NOT NULL, prev_word_id INTEGER DEFAULT 0 NOT NULL, published INTEGER DEFAULT 0 NOT NULL, section_id INTEGER DEFAULT 0 NOT NULL, word_id INTEGER DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL);
